# Loaders for the example datasets in data/.
# Pages load this with: source(here::here("R/data.R"))
#
# Add a loader here rather than reading files directly in a page, so a dataset
# used by several pages stays consistent.

#' Simulated coastal shelf survey.
#'
#' One row per survey station: where it was, what the water was like, and how many
#' individuals of one benthic species were caught.
#'
#' SIMULATED data, generated by R/make-example-data.R. Any page using it must say
#' so. The true relationships are documented at the top of that script.
load_coastal_survey <- function() {
  readr::read_csv(
    here::here("data", "coastal-survey.csv"),
    col_types = readr::cols(
      station_id        = readr::col_character(),
      survey_year       = readr::col_integer(),
      season            = readr::col_factor(c("spring", "summer", "autumn", "winter")),
      longitude         = readr::col_double(),
      latitude          = readr::col_double(),
      depth_m           = readr::col_double(),
      temperature_c     = readr::col_double(),
      salinity_psu      = readr::col_double(),
      chlorophyll_mg_m3 = readr::col_double(),
      substrate         = readr::col_factor(c("sand", "mud", "gravel", "rock")),
      abundance         = readr::col_integer(),
      present           = readr::col_factor(c("yes", "no"))
    )
  )
}

#' The same survey, as it came off the ship.
#'
#' 815 rows: the 800 station visits in `load_coastal_survey()` plus 15 duplicated
#' rows, with realistic damage and several extra columns. Read deliberately without
#' cleaning: sentinel values, inconsistent labels and text dates all arrive as they
#' are, because section 2 is about finding and fixing them.
#'
#' SIMULATED data, generated by R/make-raw-data.R from the clean extract.
load_coastal_survey_raw <- function() {
  readr::read_csv(
    here::here("data", "coastal-survey-raw.csv"),
    col_types = readr::cols(.default = readr::col_character()),
    na = character()
  ) |>
    readr::type_convert(col_types = readr::cols(
      survey_year       = readr::col_integer(),
      longitude         = readr::col_double(),
      latitude          = readr::col_double(),
      depth_m           = readr::col_double(),
      temperature_c     = readr::col_double(),
      salinity_psu      = readr::col_double(),
      chlorophyll_mg_m3 = readr::col_double(),
      abundance         = readr::col_integer(),
      catch_weight_kg   = readr::col_double(),
      .default          = readr::col_character()
    ))
}

#' The survey after the section 2 cleaning.
#'
#' Reads the raw export and applies exactly the decisions argued for in section 2:
#' drop duplicate rows, turn -999 sentinels into NA, correct the ten detectable
#' decimal-point errors in depth, and collapse the twelve substrate spellings into
#' four levels. Chlorophyll is left with its gaps: imputation belongs inside the
#' resampling, not here.
#'
#' Sections 3 onwards use this, so their pages can start from the modelling rather
#' than repeating fifteen lines of cleaning.
load_coastal_survey_clean <- function() {
  load_coastal_survey_raw() |>
    dplyr::distinct() |>
    dplyr::mutate(
      salinity_psu  = dplyr::na_if(salinity_psu, -999),
      temperature_c = dplyr::na_if(temperature_c, -999),
      depth_m       = dplyr::if_else(depth_m > 250, depth_m / 10, depth_m),
      substrate     = factor(tolower(trimws(substrate))),
      substrate     = forcats::fct_collapse(
        substrate,
        sand   = c("sand", "sandy"),
        mud    = c("mud", "muddy"),
        gravel = "gravel",
        rock   = c("rock", "rocky")
      ),
      season       = factor(season, levels = c("spring", "summer", "autumn", "winter")),
      present      = factor(present, levels = c("yes", "no")),
      rare_species = factor(rare_species, levels = c("yes", "no"))
    )
}

#' The true expected count behind each station.
#'
#' One row per station: `station_id` and `true_mean`, the expected count the
#' simulation drew from before negative-binomial noise was added.
#'
#' No real survey has this column. It exists because knowing the truth is the whole
#' point of simulating the data: it lets §5 separate a model's bias from its variance,
#' which cannot be done from observed counts alone. Join it on `station_id`.
#'
#' Never use it as a predictor, and never quote a metric computed against it as
#' though it were achievable in practice.
load_coastal_survey_truth <- function() {
  readr::read_csv(
    here::here("data", "coastal-survey-truth.csv"),
    col_types = readr::cols(
      station_id = readr::col_character(),
      true_mean  = readr::col_double()
    )
  )
}

#' Multi-taxon community matrix for the same 800 stations.
#'
#' One row per station: `station_id` and 24 taxon count columns `tax01`–`tax24`.
#' Join it to `load_coastal_survey_clean()` on `station_id` to get the environment.
#'
#' SIMULATED data, generated by R/make-community-data.R on top of the survey, so the
#' depths and substrates are the same shelf. §8 uses it because unsupervised methods
#' need many correlated columns to be worth doing, and because knowing the generating
#' process is the only way to check whether a discovered "assemblage" is real.
load_coastal_community <- function() {
  readr::read_csv(
    here::here("data", "coastal-community.csv"),
    col_types = readr::cols(
      station_id = readr::col_character(),
      .default   = readr::col_integer()
    )
  )
}

#' The traits behind each taxon in `load_coastal_community()`.
#'
#' One row per taxon: its `group` (hard-substrate, soft-substrate, generalist or
#' unrelated), its depth optimum and niche width, and its peak mean count.
#'
#' No real community matrix comes with this file. It exists so §8 can ask whether a
#' cluster or a principal component corresponds to anything that was actually put
#' into the data. Never feed it to a method as input.
load_coastal_community_taxa <- function() {
  readr::read_csv(
    here::here("data", "coastal-community-taxa.csv"),
    col_types = readr::cols(
      taxon           = readr::col_character(),
      group           = readr::col_character(),
      depth_optimum_m = readr::col_double(),
      niche_width_m   = readr::col_double(),
      peak_mean       = readr::col_double()
    )
  )
}
